-- German choose_if + faq UPDATE — generated by gen_tool_choose_faq_de_b3.py (batch 3/4)
BEGIN;
UPDATE tools SET choose_if = $t1ci$["✅ Sie möchten Studioqualität-Audio aus schlechter Aufnahme mit einem Klick — Adobe Enhance ist beste-in-Klasse", "✅ Sie sind Adobe Creative Cloud-Nutzer und möchten Audio-Enhancement in Ihrem bestehenden Workflow", "✅ Kostenloses Web-Tool für Audio-Enhancement ohne kompliziertes Setup", "✅ Sie möchten nur Audio verbessern ohne vollständigen Podcast-Editor zu benötigen"]$t1ci$::JSONB, faq = $t1fq$[{"q": "Was ist Descript?", "a": "Descript ist ein Audio- und Video-Editor der über Transkript-Bearbeitung funktioniert. Sie löschen Wörter im Text und das entsprechende Audio/Video wird automatisch entfernt. Es beinhaltet KI-Features wie Rauschentfernung, Overdub (Stimmen-Klonen) und automatische Untertitel."}, {"q": "Ist Adobe Podcast kostenlos?", "a": "Adobe Podcast Enhance (die Audio-Verbesserungsfunktion) ist auf podcast.adobe.com kostenlos nutzbar. Die vollständige Adobe Podcast-Plattform ist Teil von Creative Cloud. Descript hat einen kostenlosen Plan mit begrenzten Transkriptions-Minuten; kostenpflichtige Pläne ab $12/Monat."}, {"q": "Descript vs Riverside: Was ist besser für Podcasts?", "a": "Riverside ist besser für hochwertige Remote-Aufnahmen mit lokalem Recording für beste Qualität. Descript ist besser für Post-Production und Bearbeitung. Viele Podcaster nehmen mit Riverside auf und bearbeiten in Descript."}, {"q": "Kann Descript Stimmen klonen?", "a": "Ja. Descript's Overdub-Feature klont Ihre Stimme und kann Wörter einfügen die Sie nie gesagt haben — nützlich für Korrekturen ohne Re-Recording. Diese Funktion ist in kostenpflichtigen Plänen verfügbar und erfordert eine Trainingsphase."}]$t1fq$::JSONB WHERE slug = 'adobe-podcast' AND lang = 'de';
UPDATE tools SET choose_if = $t2ci$["✅ Sie möchten konsistente professionelle Präsentationen die automatisch schön bleiben", "✅ Smart Slide-Templates die sich automatisch anpassen wenn Sie Inhalte hinzufügen", "✅ Teams die einheitliche Markenpräsentationen ohne Design-Kenntnisse erstellen müssen", "✅ Sie möchten Folien die immer professionell aussehen ohne viel manuelle Anpassung"]$t2ci$::JSONB, faq = $t2fq$[{"q": "Gamma vs Beautiful.ai: Welches ist besser?", "a": "Gamma ist besser für die schnelle KI-generierte Erstellung aus einem Prompt. Beautiful.ai ist besser für konsistentes professionelles Design bei regelmäßigen Präsentationen. Gamma für Geschwindigkeit; Beautiful.ai für Konsistenz."}, {"q": "Ist Beautiful.ai kostenlos?", "a": "Beautiful.ai hat keinen kostenlosen Plan. Pro kostet $12/Monat (jährlich) oder $15/Monat. Gamma hat einen kostenlosen Plan mit 400 KI-Credits; Plus ab $10/Monat."}, {"q": "Kann Gamma auf Deutsch Präsentationen erstellen?", "a": "Ja. Gamma versteht deutsche Prompts und erstellt deutschsprachige Präsentationen. Geben Sie Ihren Prompt oder Outline auf Deutsch ein und Gamma generiert die Folien auf Deutsch mit passenden Layouts."}, {"q": "Beautiful.ai für Teams: Ist es gut?", "a": "Ja. Beautiful.ai hat Team-Features für Marken-Konsistenz: geteilte Farbpaletten, Schriften und Logos. Alle Team-Präsentationen sehen automatisch einheitlich aus. Für Marketing- und Vertriebs-Teams die viele Präsentationen erstellen ist das sehr wertvoll."}]$t2fq$::JSONB WHERE slug = 'beautiful-ai' AND lang = 'de';
UPDATE tools SET choose_if = $t3ci$["✅ Sie möchten eine vollständige Webanwendung mit Datenbank, Nutzeraccounts und Business-Logik bauen", "✅ Bubble ist ein vollständiges No-Code-App-Framework: Frontend, Backend und Datenbank in einem", "✅ Sie erstellen ein SaaS-Produkt, Marktplatz oder Web-App ohne Programmierkenntnisse", "✅ Startups die schnell einen MVP mit echten Funktionen (Login, Zahlungen, Daten) launchen wollen"]$t3ci$::JSONB, faq = $t3fq$[{"q": "Bubble oder Webflow: Was soll ich wählen?", "a": "Bubble für Web-Apps: Sie brauchen Nutzeraccounts, Datenbank und komplexe Logik — z.B. ein SaaS-Produkt oder Marktplatz. Webflow für Marketing-Websites: Sie brauchen eine schöne, schnelle Website mit CMS aber keine App-Logik."}, {"q": "Ist Bubble kostenlos?", "a": "Bubble hat einen kostenlosen Plan der das Bauen und Testen erlaubt. Kostenpflichtige Pläne ab $29/Monat zum Veröffentlichen ohne Bubble-Branding. Webflow hat einen kostenlosen Plan; kostenpflichtige Pläne ab $18/Monat."}, {"q": "Kann Bubble eine App für den App-Store erstellen?", "a": "Bubble erstellt Web-Apps die im Browser laufen. Für native iOS/Android-Apps können Sie Bubble-Apps als PWA verpacken oder Tools wie BDK Native verwenden. Für echte native Apps sind FlutterFlow oder React Native besser geeignet."}, {"q": "Webflow für E-Commerce: Ist das gut?", "a": "Webflow hat eingebautes E-Commerce für einfache Online-Shops. Für komplexere E-Commerce-Anforderungen (große Produktkataloge, komplexe Varianten) ist Shopify leistungsfähiger. Webflow ist gut für Design-orientierte kleine Shops."}]$t3fq$::JSONB WHERE slug = 'bubble' AND lang = 'de';
UPDATE tools SET choose_if = $t4ci$["✅ Sie möchten schnell wissen was die wissenschaftliche Forschung zu einer Frage sagt", "✅ Consensus zeigt Konsensniveau: Stimmen die meisten Studien überein oder gibt es Widersprüche?", "✅ Nicht-Wissenschaftler die evidenzbasierte Antworten auf Gesundheits- oder Ernährungsfragen suchen", "✅ Sie möchten eine schnelle Antwort mit Quellenangaben statt manuelle Paper-Recherche"]$t4ci$::JSONB, faq = $t4fq$[{"q": "Elicit vs Consensus: Was ist der Unterschied?", "a": "Elicit ist für systematische Literatur-Reviews konzipiert: Es extrahiert strukturierte Daten aus Papers für tiefe Analysen. Consensus gibt schnelle evidenzbasierte Antworten mit Konsensmessung. Elicit für Forscher; Consensus für schnelle wissenschaftliche Antworten."}, {"q": "Ist Elicit kostenlos?", "a": "Elicit hat einen kostenlosen Plan mit begrenzten Papier-Analysen. Plus ab $12/Monat. Consensus hat einen kostenlosen Plan; Premium ab $11,99/Monat. Beide haben kostenlose Testphasen."}, {"q": "Kann Elicit auf Deutsch arbeiten?", "a": "Elicit analysiert primär englischsprachige wissenschaftliche Papers da die meisten Studien auf Englisch veröffentlicht werden. Die Oberfläche ist auf Englisch. Für deutschsprachige Forschungsliteratur gibt es weniger Unterstützung."}, {"q": "Was bedeutet 'Konsensmessung' bei Consensus?", "a": "Consensus zeigt für jede Forschungsfrage ob die Studienlage überwiegend zustimmend, ablehnend oder gemischt ist. Ein 'hoher Konsens' bedeutet viele Studien stimmen überein. Das hilft Ihnen schnell einzuschätzen wie gut eine Aussage durch Forschung gestützt wird."}]$t4fq$::JSONB WHERE slug = 'consensus' AND lang = 'de';
UPDATE tools SET choose_if = $t5ci$["✅ Sie produzieren Podcasts oder Videos und möchten durch Text-Bearbeitung schneiden — Wörter löschen kürzt automatisch das Audio", "✅ KI-Rauschentfernung, Filler-Wörter-Löschung und Überblend-Funktionen in einem Tool", "✅ Sie erstellen Video-Inhalte und benötigen Untertitel, Screen-Recording und Highlight-Clips", "✅ Teams die kollaborativ an Podcasts, Webinaren oder YouTube-Content arbeiten"]$t5ci$::JSONB, faq = $t5fq$[{"q": "Was ist Descript?", "a": "Descript ist ein Audio- und Video-Editor der über Transkript-Bearbeitung funktioniert. Sie löschen Wörter im Text und das entsprechende Audio/Video wird automatisch entfernt. Es beinhaltet KI-Features wie Rauschentfernung, Overdub (Stimmen-Klonen) und automatische Untertitel."}, {"q": "Ist Adobe Podcast kostenlos?", "a": "Adobe Podcast Enhance (die Audio-Verbesserungsfunktion) ist auf podcast.adobe.com kostenlos nutzbar. Die vollständige Adobe Podcast-Plattform ist Teil von Creative Cloud. Descript hat einen kostenlosen Plan mit begrenzten Transkriptions-Minuten; kostenpflichtige Pläne ab $12/Monat."}, {"q": "Descript vs Riverside: Was ist besser für Podcasts?", "a": "Riverside ist besser für hochwertige Remote-Aufnahmen mit lokalem Recording für beste Qualität. Descript ist besser für Post-Production und Bearbeitung. Viele Podcaster nehmen mit Riverside auf und bearbeiten in Descript."}, {"q": "Kann Descript Stimmen klonen?", "a": "Ja. Descript's Overdub-Feature klont Ihre Stimme und kann Wörter einfügen die Sie nie gesagt haben — nützlich für Korrekturen ohne Re-Recording. Diese Funktion ist in kostenpflichtigen Plänen verfügbar und erfordert eine Trainingsphase."}]$t5fq$::JSONB WHERE slug = 'descript' AND lang = 'de';
UPDATE tools SET choose_if = $t6ci$["✅ Sie möchten eine Fremdsprache lernen mit KI-gestützten Erklärungen und Konversations-Praxis", "✅ Duolingo Max bietet Rollenspiel-Konversationsübungen mit KI für gesprochene Sprachpraxis", "✅ Gamifiziertes Lernen das die Motivation durch Streaks, Punkte und Liga-Wettbewerbe aufrechterhält", "✅ Sie möchten 5-15 Minuten täglich üben mit adaptivem Lernen basierend auf Ihren Schwächen"]$t6ci$::JSONB, faq = $t6fq$[{"q": "Photomath vs Mathway: Was ist besser?", "a": "Photomath ist besser für Schüler: Die Schritt-für-Schritt-Erklärungen sind didaktisch aufgebaut. Mathway löst schneller aber erklärt weniger. Photomath für Lernende; Mathway für schnelle Antworten."}, {"q": "Ist Photomath kostenlos?", "a": "Photomath ist kostenlos mit grundlegenden Lösungsschritten. Photomath Plus ($9,99/Monat oder $69,99/Jahr) bietet detailliertere Erklärungen und Animationen. Duolingo Max kostet ab $13,99/Monat als Upgrade."}, {"q": "Kann Photomath Handschrift lesen?", "a": "Ja. Photomath erkennt handgeschriebene Matheaufgaben sowie Drucktext. Die Handschrift-Erkennungsrate ist beeindruckend obwohl klare Handschrift bessere Ergebnisse liefert."}, {"q": "Duolingo Max vs Duolingo Plus: Was ist der Unterschied?", "a": "Duolingo Plus entfernt Werbung und bietet Offline-Modus. Duolingo Max ($13,99/Monat) fügt KI-Features hinzu: 'Explain My Answer' (KI erklärt Fehler) und 'Roleplay' (KI-Konversationsübungen). Max ist teurer aber bietet echten KI-Mehrwert."}]$t6fq$::JSONB WHERE slug = 'duolingo-max' AND lang = 'de';
UPDATE tools SET choose_if = $t7ci$["✅ Sie benötigen hochwertige Sprach-Synthese: Voiceovers, Hörbücher, Podcasts, Erklärvideos", "✅ Voice Cloning: Klonen Sie eine Stimme für konsistenten Content über alle Projekte", "✅ Developer-API für TTS-Integration in Apps oder automatisierte Content-Pipelines", "✅ Professionelle Sprach-Ausgabe in 30+ Sprachen für internationale Content-Produktion"]$t7ci$::JSONB, faq = $t7fq$[{"q": "Suno oder ElevenLabs: Was ist der Unterschied?", "a": "Suno generiert Musik und Songs mit Gesang. ElevenLabs generiert gesprochene Sprache und Voiceovers. Das sind grundlegend verschiedene Anwendungsfälle. Für Musik und Jingles — Suno; für Voiceovers und TTS — ElevenLabs."}, {"q": "Kann Suno deutsche Songs erstellen?", "a": "Ja. Suno kann Songs in deutschen Texten generieren. Geben Sie deutschen Liedtext in Custom Lyrics ein oder beschreiben Sie den Stil auf Deutsch. Die Qualität deutschsprachiger Songs ist gut, für Englisch aber noch konsistenter."}, {"q": "Ist Suno kostenlos?", "a": "Suno hat einen kostenlosen Plan mit 50 Credits/Tag (ca. 10 Songs). Pro ab $10/Monat (500 Credits), Premier ab $30/Monat. ElevenLabs hat einen kostenlosen Plan; Starter ab $5/Monat."}, {"q": "Kann ElevenLabs Musik generieren?", "a": "ElevenLabs fokussiert auf Text-zu-Sprache und Stimmen — keine Musik-Generierung. Für Musik nutzen Sie Suno oder Udio. ElevenLabs hat jedoch Sound Effects generierung als separate Funktion."}]$t7fq$::JSONB WHERE slug = 'elevenlabs' AND lang = 'de';
UPDATE tools SET choose_if = $t8ci$["✅ Sie recherchieren wissenschaftliche Literatur und möchten Studien systematisch extrahieren und analysieren", "✅ Elicit automatisiert das Paper-Screening und extrahiert strukturierte Daten für systematische Reviews", "✅ Sie benötigen quantitative Extraktion: Stichprobengrößen, Effektgrößen, Methoden aus Studien", "✅ Forscher die große Mengen an Papers effizient verarbeiten und meta-analytische Arbeit durchführen"]$t8ci$::JSONB, faq = $t8fq$[{"q": "Elicit vs Consensus: Was ist der Unterschied?", "a": "Elicit ist für systematische Literatur-Reviews konzipiert: Es extrahiert strukturierte Daten aus Papers für tiefe Analysen. Consensus gibt schnelle evidenzbasierte Antworten mit Konsensmessung. Elicit für Forscher; Consensus für schnelle wissenschaftliche Antworten."}, {"q": "Ist Elicit kostenlos?", "a": "Elicit hat einen kostenlosen Plan mit begrenzten Papier-Analysen. Plus ab $12/Monat. Consensus hat einen kostenlosen Plan; Premium ab $11,99/Monat. Beide haben kostenlose Testphasen."}, {"q": "Kann Elicit auf Deutsch arbeiten?", "a": "Elicit analysiert primär englischsprachige wissenschaftliche Papers da die meisten Studien auf Englisch veröffentlicht werden. Die Oberfläche ist auf Englisch. Für deutschsprachige Forschungsliteratur gibt es weniger Unterstützung."}, {"q": "Was bedeutet 'Konsensmessung' bei Consensus?", "a": "Consensus zeigt für jede Forschungsfrage ob die Studienlage überwiegend zustimmend, ablehnend oder gemischt ist. Ein 'hoher Konsens' bedeutet viele Studien stimmen überein. Das hilft Ihnen schnell einzuschätzen wie gut eine Aussage durch Forschung gestützt wird."}]$t8fq$::JSONB WHERE slug = 'elicit' AND lang = 'de';
UPDATE tools SET choose_if = $t9ci$["✅ Sie möchten KI-Meeting-Zusammenfassungen mit automatischen Aktionspunkten und Entscheidungen", "✅ Fireflies integriert mit mehr CRMs und Tools: HubSpot, Salesforce, Slack, Notion", "✅ Sie analysieren Verkaufs-Calls und möchten KI-Coaching und Sentiment-Analyse", "✅ Sales-Teams die Meeting-Insights automatisch in ihr CRM einfließen lassen wollen"]$t9ci$::JSONB, faq = $t9fq$[{"q": "Otter AI vs Fireflies AI: Was ist der Unterschied?", "a": "Otter ist stärker bei präziser Echtzeit-Transkription und einfacher Benutzeroberfläche. Fireflies ist stärker bei CRM-Integration, Sales-Intelligence und automatischen Meeting-Zusammenfassungen mit Aktionspunkten. Für Transkription — Otter; für Sales-Teams — Fireflies."}, {"q": "Ist Otter AI kostenlos?", "a": "Otter hat einen kostenlosen Plan mit 600 Minuten Transkription/Monat und 30 Minuten pro Meeting. Pro ab $16,99/Monat. Fireflies hat einen kostenlosen Plan mit 800 Minuten Storage; Pro ab $18/Monat."}, {"q": "Kann Otter AI auf Deutsch transkribieren?", "a": "Otter AI ist primär für Englisch optimiert. Die Genauigkeit bei Deutsch ist deutlich geringer als bei Englisch. Für deutsche Meeting-Transkription sind Tools wie Whisper API, Notta oder MeetGeek mit besserer Mehrsprachigkeit geeigneter."}, {"q": "Fireflies AI für Verkaufs-Teams: Lohnt es sich?", "a": "Ja. Fireflies hat spezifische Sales-Features: Call-Analyse, Deal-Tracking-Integration, CRM-Sync und Coaching-Einblicke. Für Sales-Teams die jedes Meeting automatisch in CRM-Updates und Follow-up-Aktionen umwandeln wollen ist es sehr wertvoll."}]$t9fq$::JSONB WHERE slug = 'fireflies-ai' AND lang = 'de';
UPDATE tools SET choose_if = $t10ci$["✅ Sie möchten native mobile Apps für iOS und Android mit Flutter-Code generieren", "✅ FlutterFlow exportiert echten Flutter-Code den Sie als Entwickler weiter bearbeiten können", "✅ Sie benötigen native mobile Performance und App-Store-Veröffentlichung ohne vollständige Flutter-Kenntnisse", "✅ Mobile-first: FlutterFlow ist für Apps optimiert, Bubble ist primär web-basiert"]$t10ci$::JSONB, faq = $t10fq$[{"q": "FlutterFlow vs React Native: Was ist besser?", "a": "FlutterFlow generiert Flutter-Code für native iOS/Android-Apps ohne tiefe Programmierkenntnisse. React Native erfordert JavaScript-Kenntnisse aber ist flexibler. FlutterFlow für schnellere Entwicklung; React Native für Entwickler mit JS-Erfahrung."}, {"q": "Ist FlutterFlow kostenlos?", "a": "FlutterFlow hat einen kostenlosen Plan mit eingeschränkten Features. Standard ab $30/Monat, Pro ab $70/Monat. Das Code-Export-Feature ist in kostenpflichtigen Plänen enthalten. Bubble hat einen kostenlosen Plan; ab $29/Monat zum Veröffentlichen."}, {"q": "Kann FlutterFlow in den App Store veröffentlichen?", "a": "Ja. FlutterFlow kann direkt in den Apple App Store und Google Play Store veröffentlichen. Das ist einer der größten Vorteile gegenüber Bubble das primär Web-Apps produziert."}, {"q": "FlutterFlow für Startups: Ist es gut?", "a": "FlutterFlow ist ausgezeichnet für Startups die eine mobile App schnell launchen wollen. Sie können einen MVP in Wochen statt Monaten bauen. Der Code-Export bedeutet kein Vendor Lock-in — Sie können die Entwicklung später mit Entwicklern weiterführen."}]$t10fq$::JSONB WHERE slug = 'flutterflow' AND lang = 'de';
UPDATE tools SET choose_if = $t11ci$["✅ KI-Website-Generator: beschreiben Sie Ihre Website und Framer baut sie komplett", "✅ Einfacher zu erlernen als Webflow — kürzere Lernkurve für Designer ohne CMS-Komplexität", "✅ Stärkere Animations-Features und interaktive Komponenten für kreative Marketing-Seiten", "✅ Sie möchten schnell eine Landing-Page oder Portfolio-Site ohne Webflow's Komplexität"]$t11ci$::JSONB, faq = $t11fq$[{"q": "Webflow vs Framer: Was ist einfacher?", "a": "Framer ist einfacher zu erlernen, besonders für Designer aus Figma. Webflow hat eine steilere Lernkurve aber mehr Power für komplexe Seiten. Framer für kreative Landing-Pages und Portfolios; Webflow für komplexe Content-Sites mit CMS."}, {"q": "Ist Webflow besser als WordPress?", "a": "Webflow generiert saubereren Code, ist sicherer und hat kein Plugin-Chaos. WordPress hat ein riesigeres Ökosystem und ist kostenlos. Webflow für Design-orientierte Agenturen; WordPress für Content-Sites die maximale Plugin-Auswahl brauchen."}, {"q": "Framer AI vs Webflow: Wer gewinnt für Landing-Pages?", "a": "Framer gewinnt für schnelle, animierte Landing-Pages. Webflow ist besser wenn die Landing-Page Teil einer größeren Content-Strategie mit CMS ist. Für kreative Einzel-Landing-Pages — Framer; für mehrseitige Websites mit CMS — Webflow."}, {"q": "Kann Webflow E-Commerce?", "a": "Ja. Webflow hat eingebautes E-Commerce für einfache Online-Shops. Für komplexere Anforderungen ist Shopify leistungsfähiger. Webflow E-Commerce ist gut für Design-orientierte Shops mit bis zu ein paar hundert Produkten."}]$t11fq$::JSONB WHERE slug = 'framer-ai' AND lang = 'de';
UPDATE tools SET choose_if = $t12ci$["✅ Sie möchten in Minuten professionelle Präsentationen, Dokumente oder Webseiten aus Text generieren", "✅ Schönes modernes Design out-of-the-box ohne PowerPoint-Formatierungskenntnisse", "✅ Sie bereiten Investor-Pitches, Sales-Decks oder Kunden-Präsentationen schnell vor", "✅ Gamma-Präsentationen funktionieren als interaktive Web-Decks direkt im Browser"]$t12ci$::JSONB, faq = $t12fq$[{"q": "Gamma vs PowerPoint: Was ist einfacher?", "a": "Gamma ist erheblich einfacher für die schnelle Erstellung von Präsentationen. Sie beschreiben den Inhalt und Gamma generiert Folien mit Layout und Design. PowerPoint gibt mehr Kontrolle aber erfordert mehr Aufwand. Gamma für schnelle professionelle Decks; PowerPoint für maximale Anpassung."}, {"q": "Ist Gamma kostenlos?", "a": "Gamma hat einen kostenlosen Plan mit 400 KI-Credits bei der Registrierung. Kostenpflichtige Pläne ab $10/Monat (Plus) für unbegrenzte KI und eigene Domains. Notion AI kostet $10/Benutzer/Monat zusätzlich zum Notion-Plan."}, {"q": "Kann Gamma auf Deutsch Präsentationen erstellen?", "a": "Ja. Gamma versteht deutsche Prompts und erstellt Präsentationen auf Deutsch. Die Qualität des generierten deutschen Textes ist gut. Geben Sie Ihren Prompt auf Deutsch ein und Gamma erstellt deutschsprachige Folien."}, {"q": "Gamma vs Google Slides: Was ist besser?", "a": "Gamma ist besser für schnelle KI-generierte Präsentationen mit modernem Design. Google Slides ist besser für kollaborative Bearbeitung im Team mit Google Workspace. Für Erstell-Geschwindigkeit — Gamma; für Team-Kollaboration im Google-Ökosystem — Google Slides."}]$t12fq$::JSONB WHERE slug = 'gamma' AND lang = 'de';
UPDATE tools SET choose_if = $t13ci$["✅ Sie möchten aus Google Sheets oder Airtable schnell eine mobile App oder Web-App erstellen", "✅ Glide ist einfacher: keine Workflows oder komplexe Konfiguration — einfach Daten verbinden und App ist fertig", "✅ Sie benötigen interne Business-Tools: Inventar-Apps, Mitarbeiter-Verzeichnisse, Kundenportale", "✅ Teams die Apps aus bestehenden Tabellenkalkulationen ohne Bubble's Komplexität bauen wollen"]$t13ci$::JSONB, faq = $t13fq$[{"q": "Glide vs AppSheet: Was ist besser?", "a": "Beide erstellen Apps aus Tabellenkalkulationen. AppSheet (Google) hat mehr Power für komplexe Workflows und ist kostenlos bis zu bestimmten Limits. Glide ist benutzerfreundlicher mit schönerem Design. AppSheet für komplexere Logik; Glide für schönere, einfachere Apps."}, {"q": "Ist Glide kostenlos?", "a": "Glide hat einen kostenlosen Plan für Basis-Apps mit Glide-Branding. Maker ab $49/Monat, Team ab $99/Monat für mehr Features und eigene Domain. Bubble hat einen kostenlosen Plan; ab $29/Monat zum Veröffentlichen ohne Branding."}, {"q": "Kann Glide mit Google Sheets synchronisieren?", "a": "Ja. Glide's Kerntechnologie ist die Live-Synchronisation mit Google Sheets und Airtable. Änderungen in der App werden in Echtzeit in Ihr Spreadsheet geschrieben und umgekehrt. Das macht Glide ideal wenn Ihre Daten bereits in Sheets leben."}, {"q": "Glide für kleine Unternehmen: Ist es geeignet?", "a": "Ja. Glide ist besonders gut für kleine Unternehmen die einfache interne Tools brauchen: Inventar-Verwaltung, Kunden-CRM, Mitarbeiter-Verzeichnisse. Die Lernkurve ist minimal und der Einstieg schnell."}]$t13fq$::JSONB WHERE slug = 'glide' AND lang = 'de';
UPDATE tools SET choose_if = $t14ci$["✅ Sie sind Data Scientist oder Analyst der SQL und Python für kollaborative Analysen in Notebooks nutzt", "✅ Hex kombiniert Notebook-Umgebung mit App-Publishing: Analysen werden zu interaktiven Dashboards", "✅ KI-Unterstützung beim Schreiben von SQL und Python-Code direkt im Notebook", "✅ Teams die komplexe reproduzierbare Analysen in einem kollaborativen Notebook-Umfeld entwickeln"]$t14ci$::JSONB, faq = $t14fq$[{"q": "Was ist Hex?", "a": "Hex ist eine kollaborative Datenplattform die Notebooks (SQL + Python) mit App-Publishing kombiniert. Data-Teams schreiben Analysen in Hex-Notebooks und veröffentlichen sie als interaktive Dashboards für nicht-technische Stakeholder — ohne separates BI-Tool."}, {"q": "Hex vs Databricks: Was ist der Unterschied?", "a": "Hex ist ein kollaboratives Notebook-Tool mit App-Publishing. Databricks ist eine vollständige Data Lakehouse-Plattform für Enterprise-Scale Data Engineering und ML. Hex für kollaborative Analyse-Teams; Databricks für groß angelegte Daten-Infrastruktur."}, {"q": "Ist Hex kostenlos?", "a": "Hex hat einen kostenlosen Plan für individuelle Nutzer mit begrenzten Projekten. Team-Pläne beginnen ab $24/Benutzer/Monat. Looker Studio ist vollständig kostenlos."}, {"q": "Hex vs Jupyter Notebooks: Was ist besser?", "a": "Jupyter ist kostenlos und Open-Source aber erfordert lokale Installation und hat wenig eingebaute Kollaboration. Hex ist Cloud-basiert, kollaborativ und fügt App-Publishing ohne zusätzliche Tools hinzu. Hex für Teams; Jupyter für individuelle lokale Entwicklung."}]$t14fq$::JSONB WHERE slug = 'hex' AND lang = 'de';
UPDATE tools SET choose_if = $t15ci$["✅ Sie verarbeiten große Mengen an PDFs und benötigen schnelle Antworten mit präzisen Seitenangaben", "✅ Humata zeigt genau welche Seite und welcher Absatz die Antwort enthält", "✅ Sie benötigen Team-Sharing für geteilte Dokument-Bibliotheken in Unternehmen", "✅ Sie möchten mehrere Dokumente gleichzeitig analysieren und vergleichen"]$t15ci$::JSONB, faq = $t15fq$[{"q": "NotebookLM vs ChatGPT für Dokumente?", "a": "NotebookLM ist spezialisiert auf Ihre eigenen Quellen — es antwortet nur basierend auf den Dokumenten die Sie hinzufügen. ChatGPT hat allgemeines Weltwissen und kann auch Dokumente analysieren. NotebookLM für präzise quellenbasierte Recherche; ChatGPT für allgemeinere Analysen."}, {"q": "Ist NotebookLM kostenlos?", "a": "Ja. NotebookLM ist kostenlos auf notebooklm.google.com. NotebookLM Plus ist in Google One AI Premium ($19,99/Monat) enthalten und bietet mehr Notebooks und höhere Limits."}, {"q": "Was ist Humata?", "a": "Humata ist ein KI-Tool für PDF-Analyse das präzise Antworten mit genauen Quellangaben (Seitenzahlen, Absätze) liefert. Es ist besonders für Unternehmen geeignet die große Dokumentenmengen verarbeiten und Team-Features benötigen."}, {"q": "Kann NotebookLM deutschen Dokumenten analysieren?", "a": "Ja. NotebookLM kann PDFs und Dokumente in Deutsch analysieren. Die KI versteht Deutsch und kann Fragen auf Deutsch beantworten. Für deutschen akademischen oder juristischen Content ist es gut geeignet."}]$t15fq$::JSONB WHERE slug = 'humata' AND lang = 'de';
UPDATE tools SET choose_if = $t16ci$["✅ Sie möchten Daten in natürlicher Sprache analysieren: 'Zeig mir den Umsatztrend der letzten 6 Monate'", "✅ Julius kann Python-Code schreiben und ausführen für fortgeschrittene statistische Analysen", "✅ Sie laden CSV/Excel-Dateien hoch und erhalten sofort KI-Analysen und Visualisierungen", "✅ Nicht-technische Nutzer die Datenanalyse ohne SQL oder Python-Kenntnisse durchführen wollen"]$t16ci$::JSONB, faq = $t16fq$[{"q": "Was ist Julius AI?", "a": "Julius AI ist ein KI-Datenanalyse-Tool das natürlichsprachige Fragen zu Ihren Daten beantwortet. Sie laden eine CSV, Excel oder verbinden eine Datenquelle und Julius analysiert, erstellt Grafiken und führt statistische Berechnungen durch — ohne SQL oder Python."}, {"q": "Ist Julius AI kostenlos?", "a": "Julius AI hat einen kostenlosen Plan mit begrenzten Nachrichten/Monat. Pro ab $22,99/Monat. Looker Studio ist vollständig kostenlos."}, {"q": "Julius AI vs ChatGPT für Datenanalyse?", "a": "Julius AI ist spezialisiert auf Datenanalyse mit direkter Datenverbindung und Code-Ausführung. ChatGPT Advanced Data Analysis (Code Interpreter) kann ähnliches aber ist allgemeiner. Julius für kontinuierliche Datenanalyse; ChatGPT für einmalige Analysen."}, {"q": "Kann Julius AI auf Deutsch arbeiten?", "a": "Ja. Julius AI versteht deutsche Anfragen und kann auf Deutsch antworten. Sie können Ihre Datenfragen auf Deutsch stellen und erhalten Analysen und Erklärungen auf Deutsch."}]$t16fq$::JSONB WHERE slug = 'julius-ai' AND lang = 'de';
UPDATE tools SET choose_if = $t17ci$["✅ Sie lernen nicht nur Mathe sondern viele Fächer: Geschichte, Programmierung, Naturwissenschaften", "✅ Khanmigo erklärt durch Fragen (Sokrates-Methode) statt direkte Antworten zu geben — tieferes Verstehen", "✅ KI-Tutor der sich an Ihren Lernstand anpasst und gezielt auf Schwächen eingeht", "✅ Schüler die begleitetes Lernen bevorzugen über einfache Aufgaben-Lösung"]$t17ci$::JSONB, faq = $t17fq$[{"q": "Was ist Khanmigo?", "a": "Khanmigo ist Khan Academy's KI-Tutor powered by GPT-4. Er nutzt die Sokrates-Methode: statt Antworten zu geben stellt er Fragen die den Schüler zum richtigen Denken führen. Verfügbar für alle Khan Academy-Inhalte: Mathe, Naturwissenschaften, Geschichte, Programmierung."}, {"q": "Wie viel kostet Khanmigo?", "a": "Khanmigo kostet $4/Monat als Add-on zu Khan Academy. Photomath ist kostenlos mit Basis-Features; Plus ab $9,99/Monat. Khanmigo ist günstiger wenn Sie einen vollständigen KI-Tutor für viele Fächer benötigen."}, {"q": "Khanmigo für Deutsch lernen: Kann es das?", "a": "Khanmigo ist primär auf Englisch verfügbar und für englischsprachige Khan Academy-Inhalte optimiert. Für Deutsch als Fremdsprache sind Duolingo, Babbel oder andere Sprachlern-Apps besser geeignet."}, {"q": "Photomath für Erwachsene: Ist es geeignet?", "a": "Ja. Photomath ist für jeden nützlich der Mathematik verstehen möchte — nicht nur Schüler. Studenten, Eltern die Kindern helfen, und Erwachsene die Mathe auffrischen nutzen Photomath erfolgreich."}]$t17fq$::JSONB WHERE slug = 'khanmigo' AND lang = 'de';
UPDATE tools SET choose_if = $t18ci$["✅ Sie möchten Google Analytics, Google Ads und Sheets-Daten kostenlos visualisieren", "✅ Sie sind im Google-Ökosystem und benötigen schnelle kostenlose Dashboards ohne steile Lernkurve", "✅ Marketing-Teams die monatliche Performance-Reports für Kunden oder Management erstellen", "✅ Kleine Unternehmen die professionelle Daten-Dashboards ohne Enterprise-Budget benötigen"]$t18ci$::JSONB, faq = $t18fq$[{"q": "Looker Studio vs Tableau: Was ist besser?", "a": "Looker Studio (kostenlos) ist ideal für Google-Ökosystem-Daten und einfache Marketing-Dashboards. Tableau ist leistungsfähiger für komplexe Unternehmensanalysen aber kostet ab $75/Benutzer/Monat. Für kleine Teams und Marketing — Looker Studio; für Enterprise-BI — Tableau."}, {"q": "Ist Looker Studio wirklich kostenlos?", "a": "Ja. Looker Studio ist vollständig kostenlos für Einzelnutzer. Looker Studio Pro kostet $9/Benutzer/Monat und fügt erweiterte Verwaltungs- und Kollaborations-Features für Teams hinzu."}, {"q": "Kann Tableau AI natürliche Sprache verwenden?", "a": "Ja. Tableau hat Ask Data und Tableau AI Features die natürlichsprachige Fragen zu Ihren Daten ermöglichen. Sie können fragen 'Was waren unsere Top-Produkte letztes Quartal?' und Tableau generiert die Visualisierung."}, {"q": "Looker Studio vs Power BI: Was ist besser?", "a": "Beide sind starke Dashboard-Tools. Looker Studio ist kostenlos und Google-zentriert. Power BI ($10/Benutzer/Monat) ist tiefer in Microsoft 365 integriert und leistungsfähiger für komplexe Datenmodelle. Im Google-Ökosystem — Looker Studio; im Microsoft-Ökosystem — Power BI."}]$t18fq$::JSONB WHERE slug = 'looker-studio' AND lang = 'de';
UPDATE tools SET choose_if = $t19ci$["✅ Sie beschreiben Ihre App in natürlicher Sprache und Lovable generiert vollständigen React-Code", "✅ Sie möchten echten exportierbaren Code — kein proprietäres No-Code-System das Sie einsperrt", "✅ Entwickler die die Entwicklung beschleunigen wollen aber echten Code als Output bevorzugen", "✅ Sie möchten KI-Unterstützung die wirklich programmiert nicht nur visuelle Bausteine verschiebt"]$t19ci$::JSONB, faq = $t19fq$[{"q": "Was ist Lovable?", "a": "Lovable ist ein KI-App-Builder der vollständigen React-Code aus natürlichsprachigen Beschreibungen generiert. Sie beschreiben Ihre App, Lovable schreibt den Code, und Sie können ihn exportieren oder direkt deployen. Es kombiniert KI-Codierung mit No-Code-Einfachheit."}, {"q": "Lovable vs Bolt.new: Was ist besser?", "a": "Beide generieren echten Code aus natürlicher Sprache. Lovable hat ein stärkeres Design-System und UI-Generierung. Bolt.new von StackBlitz ist stärker für Entwickler die Code direkt bearbeiten möchten. Beide sind ausgezeichnet — testen Sie beide für Ihr spezifisches Projekt."}, {"q": "Ist Lovable kostenlos?", "a": "Lovable hat einen kostenlosen Plan mit begrenzten Nachrichten/Monat. Pro ab $20/Monat für mehr KI-Interaktionen und erweiterte Features. Bubble hat einen kostenlosen Plan; kostenpflichtige Pläne ab $29/Monat."}, {"q": "Kann Lovable eine Datenbank verbinden?", "a": "Ja. Lovable kann mit Supabase integriert werden für Backend-Daten und Authentifizierung. Das ermöglicht vollständige Web-Apps mit Datenbank-Funktionalität durch KI-generierten Code."}]$t19fq$::JSONB WHERE slug = 'lovable' AND lang = 'de';
UPDATE tools SET choose_if = $t20ci$["✅ Sie benötigen komplexere Workflows mit visueller Drag-and-Drop-Oberfläche und mehr Kontrolle", "✅ Make ist deutlich günstiger als Zapier bei höheren Automatisierungsvolumen", "✅ Sie möchten Fehler-Handling, Iteration über Arrays und komplexe Daten-Transformationen", "✅ Entwickler und fortgeschrittene Nutzer die mehr Flexibilität als Zapier's einfaches Modell benötigen"]$t20ci$::JSONB, faq = $t20fq$[{"q": "Zapier vs Make: Was ist günstiger?", "a": "Make ist deutlich günstiger bei gleicher Aufgabenmenge. Zapier berechnet pro Task-Ausführung; Make berechnet pro Operation aber mit günstigeren Preisen. Für hohe Volumen und technische Teams — Make; für Einfachheit und breite App-Unterstützung — Zapier."}, {"q": "Ist Zapier kostenlos?", "a": "Zapier hat einen kostenlosen Plan mit 100 Tasks/Monat und 5 Zaps. Kostenpflichtige Pläne ab $29,99/Monat (Starter). Make hat einen kostenlosen Plan mit 1.000 Operationen/Monat; kostenpflichtige Pläne ab $9/Monat."}, {"q": "Was ist ein Zap?", "a": "Ein Zap ist ein automatischer Workflow in Zapier: 'Wenn X passiert (Trigger), führe Y aus (Action)'. Zum Beispiel: 'Wenn ich eine E-Mail mit Anhang bekomme, speichere den Anhang in Google Drive und sende eine Slack-Benachrichtigung'."}, {"q": "Make vs n8n: Was ist besser?", "a": "Make ist benutzerfreundlicher mit Cloud-Hosting inklusive. n8n ist Open-Source und kann selbst gehostet werden — praktisch kostenlos bei eigenem Server. Für technische Teams mit Datenschutz-Anforderungen — n8n; für einfachere Bedienung mit Cloud-Hosting — Make."}]$t20fq$::JSONB WHERE slug = 'make' AND lang = 'de';
UPDATE tools SET choose_if = $t21ci$["✅ Sie möchten automatisches KI-Scheduling: Motion plant Aufgaben und Meetings automatisch in Ihren Kalender", "✅ Kombiniertes Projektmanagement, Kalender und Zeitplanung in einer App", "✅ Sie haben viele Projekte und Aufgaben die automatisch nach Priorität geplant werden sollen", "✅ Einzelpersonen und kleine Teams die manuelle Planung vollständig an KI delegieren möchten"]$t21ci$::JSONB, faq = $t21fq$[{"q": "Motion vs Reclaim AI: Welches ist besser?", "a": "Motion ist ein vollständiges Produktivitäts-System mit Projektmanagement und KI-Scheduling. Reclaim ist spezifischer: Es schützt Fokuszeiten und optimiert Ihren bestehenden Google-Kalender. Motion für vollständige Planung; Reclaim für intelligente Kalender-Optimierung."}, {"q": "Wie viel kostet Motion?", "a": "Motion kostet ab $19/Monat (Individual) oder $12/Monat bei jährlicher Zahlung. Reclaim AI hat einen kostenlosen Plan; kostenpflichtige Pläne ab $10/Monat. Beide bieten kostenlose Testphasen."}, {"q": "Funktioniert Reclaim mit Google Kalender?", "a": "Ja. Reclaim AI ist primär für Google Kalender entwickelt und integriert sich tief. Es schützt Fokuszeiten, plant Habits ein und optimiert Meeting-Scheduling automatisch. Outlook-Integration ist ebenfalls verfügbar."}, {"q": "Kann Motion Teamprojekte verwalten?", "a": "Ja. Motion hat Team-Features: gemeinsame Projektplanung, Task-Zuweisung und Team-Kalender. Es plant Aufgaben automatisch basierend auf Verfügbarkeit und Priorität für das gesamte Team."}]$t21fq$::JSONB WHERE slug = 'motion' AND lang = 'de';
UPDATE tools SET choose_if = $t22ci$["✅ Sie haben eigene Dokumente (PDFs, Artikel, Notizen) und möchten KI-Fragen dazu stellen", "✅ Forschungs-Assistent: analysiert Ihre Quellen, nicht das Web", "✅ Audio-Übersichten: NotebookLM generiert Podcast-ähnliche Zusammenfassungen Ihrer Dokumente", "✅ Sie möchten sichergehen dass KI-Antworten nur auf Ihren spezifischen Quellen basieren"]$t22ci$::JSONB, faq = $t22fq$[{"q": "Perplexity vs Google: Was ist der Unterschied?", "a": "Perplexity fasst die Antwort direkt zusammen mit zitierten Quellen — kein Link-Scrollen nötig. Google gibt Links die Sie selbst besuchen müssen. Perplexity ist schneller für direkte Antworten; Google ist besser für explorative Suche und komplexe Themen."}, {"q": "Ist Perplexity kostenlos?", "a": "Perplexity hat einen kostenlosen Plan mit begrenzten Pro-Suchen. Perplexity Pro ($20/Monat) bietet unbegrenzte Pro-Suchen, GPT-4o, Claude, Gemini und Bildgenerierung. NotebookLM ist kostenlos."}, {"q": "Kann NotebookLM YouTube-Videos analysieren?", "a": "Ja. NotebookLM akzeptiert YouTube-Video-Links als Quellen und transkribiert den Inhalt automatisch. Sie können dann Fragen zum Video-Inhalt stellen. Das ist ein einzigartiges Feature das Perplexity nicht hat."}, {"q": "Perplexity für akademische Recherche: Ist es gut?", "a": "Perplexity ist gut für schnelle Literatursuche und Überblicke. Für tiefe akademische Forschung sind Semantic Scholar, Elicit oder Consensus besser — sie sind speziell für peer-reviewed Literatur optimiert. Perplexity als erster Schritt; spezialisierte Tools für tiefere Analyse."}]$t22fq$::JSONB WHERE slug = 'notebooklm' AND lang = 'de';
UPDATE tools SET choose_if = $t23ci$["✅ Ihr Team arbeitet in Notion und möchte KI direkt in Notizen, Dokumente und Datenbanken integriert haben", "✅ KI-gestütztes Schreiben, Zusammenfassen und Übersetzen von Dokumenten ohne Tool-Wechsel", "✅ Sie möchten Ihre Notion-Wissensdatenbank mit KI durchsuchen und Antworten generieren", "✅ Content-Teams die Meeting-Notizen, Projektbriefings und Dokumente in Notion verwalten"]$t23ci$::JSONB, faq = $t23fq$[{"q": "Notion AI vs ChatGPT: Was ist besser?", "a": "Notion AI ist nativ in Notion integriert und arbeitet mit Ihren vorhandenen Dokumenten. ChatGPT ist ein eigenständiger Assistent ohne Ihre Dokument-Basis. Notion AI für bestehende Notion-Nutzer; ChatGPT für allgemeine KI-Aufgaben außerhalb von Notion."}, {"q": "Was kostet Notion AI?", "a": "Notion AI ist ein Add-on für $10/Benutzer/Monat zusätzlich zum Notion-Plan. Zapier hat eine kostenlose Version mit 100 Aufgaben/Monat; kostenpflichtige Pläne ab $29,99/Monat."}, {"q": "Kann Zapier KI-Workflows erstellen?", "a": "Ja. Zapier hat KI-Funktionen: AI-gestützte Zap-Generierung, Formatter mit KI und AI-Steps in Workflows. Sie können KI-Verarbeitung als Schritt in Automationen einbauen — z.B. E-Mail-Inhalt zusammenfassen und in Notion speichern."}, {"q": "Notion AI für Teams: Ist es gut?", "a": "Ja. Notion AI ist besonders wertvoll für Teams die Notion als zentrales Wissens-Hub nutzen. Es kann Meeting-Notizen automatisch zusammenfassen, Action Items extrahieren und Dokumente übersetzen — direkt in Ihren bestehenden Workflows."}]$t23fq$::JSONB WHERE slug = 'notion-ai' AND lang = 'de';
UPDATE tools SET choose_if = $t24ci$["✅ Sie transkribieren Interviews oder Meetings und möchten die genaueste Echtzeit-Transkription", "✅ Otter ist tiefer in Zoom, Google Meet und Teams integriert — automatischer Meeting-Assistent", "✅ Kollaborative Transkripte: Highlights setzen, kommentieren, Aktionspunkte markieren", "✅ Studenten und Journalisten die präzise Transkriptionen für Interviews und Vorlesungen benötigen"]$t24ci$::JSONB, faq = $t24fq$[{"q": "Otter AI vs Fireflies AI: Was ist der Unterschied?", "a": "Otter ist stärker bei präziser Echtzeit-Transkription und einfacher Benutzeroberfläche. Fireflies ist stärker bei CRM-Integration, Sales-Intelligence und automatischen Meeting-Zusammenfassungen mit Aktionspunkten. Für Transkription — Otter; für Sales-Teams — Fireflies."}, {"q": "Ist Otter AI kostenlos?", "a": "Otter hat einen kostenlosen Plan mit 600 Minuten Transkription/Monat und 30 Minuten pro Meeting. Pro ab $16,99/Monat. Fireflies hat einen kostenlosen Plan mit 800 Minuten Storage; Pro ab $18/Monat."}, {"q": "Kann Otter AI auf Deutsch transkribieren?", "a": "Otter AI ist primär für Englisch optimiert. Die Genauigkeit bei Deutsch ist deutlich geringer als bei Englisch. Für deutsche Meeting-Transkription sind Tools wie Whisper API, Notta oder MeetGeek mit besserer Mehrsprachigkeit geeigneter."}, {"q": "Fireflies AI für Verkaufs-Teams: Lohnt es sich?", "a": "Ja. Fireflies hat spezifische Sales-Features: Call-Analyse, Deal-Tracking-Integration, CRM-Sync und Coaching-Einblicke. Für Sales-Teams die jedes Meeting automatisch in CRM-Updates und Follow-up-Aktionen umwandeln wollen ist es sehr wertvoll."}]$t24fq$::JSONB WHERE slug = 'otter-ai' AND lang = 'de';
UPDATE tools SET choose_if = $t25ci$["✅ Sie benötigen Echtzeit-Websuche mit zitierten Quellen — Perplexity ist die beste KI-Suchmaschine", "✅ Sie möchten aktuelle Nachrichten, Preise oder Informationen die ein statisches LLM nicht kennt", "✅ Schnelle Faktenchecks und Recherchen mit direkten Quellen-Links für Verifikation", "✅ Sie möchten einen Google-Ersatz mit KI-Zusammenfassungen statt langer Link-Listen"]$t25ci$::JSONB, faq = $t25fq$[{"q": "Perplexity vs Google: Was ist der Unterschied?", "a": "Perplexity fasst die Antwort direkt zusammen mit zitierten Quellen — kein Link-Scrollen nötig. Google gibt Links die Sie selbst besuchen müssen. Perplexity ist schneller für direkte Antworten; Google ist besser für explorative Suche und komplexe Themen."}, {"q": "Ist Perplexity kostenlos?", "a": "Perplexity hat einen kostenlosen Plan mit begrenzten Pro-Suchen. Perplexity Pro ($20/Monat) bietet unbegrenzte Pro-Suchen, GPT-4o, Claude, Gemini und Bildgenerierung. NotebookLM ist kostenlos."}, {"q": "Kann NotebookLM YouTube-Videos analysieren?", "a": "Ja. NotebookLM akzeptiert YouTube-Video-Links als Quellen und transkribiert den Inhalt automatisch. Sie können dann Fragen zum Video-Inhalt stellen. Das ist ein einzigartiges Feature das Perplexity nicht hat."}, {"q": "Perplexity für akademische Recherche: Ist es gut?", "a": "Perplexity ist gut für schnelle Literatursuche und Überblicke. Für tiefe akademische Forschung sind Semantic Scholar, Elicit oder Consensus besser — sie sind speziell für peer-reviewed Literatur optimiert. Perplexity als erster Schritt; spezialisierte Tools für tiefere Analyse."}]$t25fq$::JSONB WHERE slug = 'perplexity' AND lang = 'de';
UPDATE tools SET choose_if = $t26ci$["✅ Sie möchten Matheaufgaben mit der Kamera lösen und Schritt-für-Schritt-Erklärungen erhalten", "✅ Schüler die Mathematik verstehen wollen — nicht nur die Antwort sondern den Lösungsweg", "✅ Deckt alle Mathe-Level ab: Grundschule bis Infinitesimalrechnung und Lineare Algebra", "✅ Hausaufgabenhilfe die erklärt statt nur zu lösen — ideal für selbstständiges Lernen"]$t26ci$::JSONB, faq = $t26fq$[{"q": "Photomath vs Mathway: Was ist besser?", "a": "Photomath ist besser für Schüler: Die Schritt-für-Schritt-Erklärungen sind didaktisch aufgebaut. Mathway löst schneller aber erklärt weniger. Photomath für Lernende; Mathway für schnelle Antworten."}, {"q": "Ist Photomath kostenlos?", "a": "Photomath ist kostenlos mit grundlegenden Lösungsschritten. Photomath Plus ($9,99/Monat oder $69,99/Jahr) bietet detailliertere Erklärungen und Animationen. Duolingo Max kostet ab $13,99/Monat als Upgrade."}, {"q": "Kann Photomath Handschrift lesen?", "a": "Ja. Photomath erkennt handgeschriebene Matheaufgaben sowie Drucktext. Die Handschrift-Erkennungsrate ist beeindruckend obwohl klare Handschrift bessere Ergebnisse liefert."}, {"q": "Duolingo Max vs Duolingo Plus: Was ist der Unterschied?", "a": "Duolingo Plus entfernt Werbung und bietet Offline-Modus. Duolingo Max ($13,99/Monat) fügt KI-Features hinzu: 'Explain My Answer' (KI erklärt Fehler) und 'Roleplay' (KI-Konversationsübungen). Max ist teurer aber bietet echten KI-Mehrwert."}]$t26fq$::JSONB WHERE slug = 'photomath' AND lang = 'de';
UPDATE tools SET choose_if = $t27ci$["✅ Sie erstellen Investor-Decks und Sales-Präsentationen die professionell ausgearbeitet werden", "✅ Pitch hat stärkere Team-Kollaborations-Features: Kommentare, Live-Editing, Version-History", "✅ Schönere ausgereiftere Präsentations-Templates speziell für Startup-Pitches und Business-Decks", "✅ Pitch Analytics zeigt wer Ihren Deck angesehen hat und wie lange auf jeder Folie"]$t27ci$::JSONB, faq = $t27fq$[{"q": "Gamma vs Pitch: Was ist besser für Startups?", "a": "Pitch ist besser für polierte Investor-Decks: professionellere Templates, stärkere Kollaboration und Analytics. Gamma ist besser für schnelle erste Entwürfe oder wenn KI den Inhalt generieren soll. Für finale Investor-Präsentation — Pitch; für schnelle Entwürfe — Gamma."}, {"q": "Ist Pitch kostenlos?", "a": "Pitch hat einen kostenlosen Plan für bis zu 3 Mitglieder. Pro ab $8/Mitglied/Monat für unbegrenzte Präsentationen und alle Features. Gamma hat einen kostenlosen Plan mit 400 Credits; Plus ab $10/Monat."}, {"q": "Kann Pitch KI-Inhalte generieren?", "a": "Pitch hat KI-Features zum Verfassen von Inhalten und Vorschläge für Slides. Es ist aber weniger KI-zentriert als Gamma. Gamma generiert vollständige Präsentationen aus Prompts; Pitch's KI hilft beim Verfeinern."}, {"q": "Pitch Analytics: Was zeigt es?", "a": "Pitch Analytics zeigt für geteilte Decks: wer den Link geöffnet hat, wie lange sie geschaut haben, auf welchen Folien sie Zeit verbracht haben und ob sie weitergeleitet haben. Das ist wertvoll für Sales-Teams die wissen wollen ob Interessenten den Deck wirklich durchgesehen haben."}]$t27fq$::JSONB WHERE slug = 'pitch' AND lang = 'de';
UPDATE tools SET choose_if = $t28ci$["✅ Sie möchten spezifische Zeitblöcke schützen: Tiefarbeit, Pausen, Routinen automatisch einplanen", "✅ Reclaim passt Ihren Google-Kalender automatisch an wenn sich Meetings verschieben", "✅ Team-Synchronisation: Reclaim findet automatisch die besten Meeting-Zeiten für alle Beteiligten", "✅ Sie nutzen Google Kalender und möchten smarte automatische Optimierung ohne vollständigen App-Wechsel"]$t28ci$::JSONB, faq = $t28fq$[{"q": "Motion vs Reclaim AI: Welches ist besser?", "a": "Motion ist ein vollständiges Produktivitäts-System mit Projektmanagement und KI-Scheduling. Reclaim ist spezifischer: Es schützt Fokuszeiten und optimiert Ihren bestehenden Google-Kalender. Motion für vollständige Planung; Reclaim für intelligente Kalender-Optimierung."}, {"q": "Wie viel kostet Motion?", "a": "Motion kostet ab $19/Monat (Individual) oder $12/Monat bei jährlicher Zahlung. Reclaim AI hat einen kostenlosen Plan; kostenpflichtige Pläne ab $10/Monat. Beide bieten kostenlose Testphasen."}, {"q": "Funktioniert Reclaim mit Google Kalender?", "a": "Ja. Reclaim AI ist primär für Google Kalender entwickelt und integriert sich tief. Es schützt Fokuszeiten, plant Habits ein und optimiert Meeting-Scheduling automatisch. Outlook-Integration ist ebenfalls verfügbar."}, {"q": "Kann Motion Teamprojekte verwalten?", "a": "Ja. Motion hat Team-Features: gemeinsame Projektplanung, Task-Zuweisung und Team-Kalender. Es plant Aufgaben automatisch basierend auf Verfügbarkeit und Priorität für das gesamte Team."}]$t28fq$::JSONB WHERE slug = 'reclaim-ai' AND lang = 'de';
UPDATE tools SET choose_if = $t29ci$["✅ Sie möchten interne Tools und Admin-Panels bauen: CRUD-Interfaces, Datenbank-UIs, Operations-Dashboards", "✅ Retool AI generiert UI-Komponenten und Code für interne Tools mit KI-Unterstützung", "✅ Entwickler die schnell interne Tools für ihre Teams ohne full-stack Entwicklung bauen wollen", "✅ Sie benötigen direkten Datenbankzugang und CRUD-Operationen in einem No-Code-Interface"]$t29ci$::JSONB, faq = $t29fq$[{"q": "Was ist Retool?", "a": "Retool ist eine Low-Code-Plattform für interne Tools. Entwickler verbinden Datenbanken und APIs und bauen Admin-Panels, CRUD-Interfaces und Operations-Dashboards visuell. Retool AI fügt KI-gestützte Komponenten-Generierung und Workflow-Automation hinzu."}, {"q": "Wie viel kostet Retool?", "a": "Retool hat einen kostenlosen Plan für bis zu 5 Benutzer. Team-Pläne ab $10/Benutzer/Monat. Looker Studio ist vollständig kostenlos. Retool ist deutlich teurer aber bietet volle Interaktivität und Backend-Integration."}, {"q": "Retool vs Appsmith: Was ist besser?", "a": "Appsmith ist Open-Source und kann selbst gehostet werden — praktisch kostenlos für eigene Server. Retool ist ausgereifter mit mehr eingebauten Komponenten und besserem Support. Für Open-Source und Kostenersparnis — Appsmith; für ausgereifte Plattform — Retool."}, {"q": "Kann Retool mit PostgreSQL verbinden?", "a": "Ja. Retool verbindet sich direkt mit PostgreSQL, MySQL, MongoDB, Supabase und vielen anderen Datenbanken. Sie können SQL-Queries schreiben und die Ergebnisse direkt in interaktiven UI-Komponenten anzeigen."}]$t29fq$::JSONB WHERE slug = 'retool-ai' AND lang = 'de';
UPDATE tools SET choose_if = $t30ci$["✅ Sie möchten eine Tabellenkalkulation mit Live-Daten-Verbindungen zu APIs, Google Analytics, Stripe, Salesforce", "✅ Rows kombiniert vertraute Spreadsheet-Oberfläche mit automatischen Daten-Imports und KI-Formeln", "✅ Nicht-Programmierer die Daten aus verschiedenen Quellen im Spreadsheet-Interface zusammenführen", "✅ Sie teilen interaktive Daten-Reports als schöne Webseiten ohne separates Dashboard-Tool"]$t30ci$::JSONB, faq = $t30fq$[{"q": "Was ist Rows?", "a": "Rows ist eine KI-gestützte Tabellenkalkulation mit eingebauten Integrationen zu über 50 Datenquellen (Google Analytics, Stripe, Airtable, APIs). Sie können Live-Daten direkt in Spreadsheet-Formeln abfragen ohne Code zu schreiben."}, {"q": "Ist Rows besser als Google Sheets?", "a": "Rows ist besser für Daten-Integrations-Workflows: Live-Verbindungen zu APIs, automatische Updates und schönere Sharing-Optionen. Google Sheets ist kostenlos, weit verbreitet und hat mehr Integrationen durch Google Workspace. Rows für Daten-Teams; Sheets für allgemeine Teamarbeit."}, {"q": "Ist Rows kostenlos?", "a": "Rows hat einen kostenlosen Plan mit 2 Tabellen und begrenzten Integrationen. Pro ab $49/Monat für Teams. Hex hat einen kostenlosen Plan für Einzelnutzer; Team-Pläne ab $24/Benutzer/Monat."}, {"q": "Kann Rows mit Zapier integriert werden?", "a": "Ja. Rows hat direkte Integrationen mit vielen Tools und kann über APIs mit Zapier verbunden werden. Die eingebauten Integrationen (Stripe, Salesforce, HubSpot) sind direkt verfügbar ohne Zapier."}]$t30fq$::JSONB WHERE slug = 'rows' AND lang = 'de';
UPDATE tools SET choose_if = $t31ci$["✅ Sie möchten wissen ob eine Studie von späteren Forschern gestützt oder widerlegt wurde (Smart Citations)", "✅ Scite zeigt den Kontext jeder Zitation: unterstützend, widersprechend oder neutral", "✅ Sie evaluieren die Robustheit einer Forschungsfindung über mehrere Studien hinweg", "✅ Forscher die die wissenschaftliche Akzeptanz und Replikierbarkeit einer Studie prüfen wollen"]$t31ci$::JSONB, faq = $t31fq$[{"q": "Was sind Smart Citations bei Scite?", "a": "Scite analysiert wie Studien in späteren Papers zitiert werden — ob die zitierende Studie die ursprüngliche Findung unterstützt, widerlegt oder neutral erwähnt. Das gibt Ihnen sofort einen Überblick über die wissenschaftliche Akzeptanz einer Studie."}, {"q": "Ist Semantic Scholar kostenlos?", "a": "Ja. Semantic Scholar ist vollständig kostenlos auf semanticscholar.org. Es wird vom Allen Institute for AI betrieben. Scite hat einen kostenlosen Plan mit begrenztem Zugang; kostenpflichtige Pläne ab $20/Monat."}, {"q": "Scite vs PubMed: Was ist besser?", "a": "PubMed ist die primäre Datenbank für biomedizinische Literatur — am vollständigsten und aktuellsten für Medizin. Scite fügt eine wichtige Dimension hinzu: die Qualität der Zitationen. Für biomedizinische Forschung — PubMed als Primärquelle, Scite für Qualitätsbewertung."}, {"q": "Kann Semantic Scholar auf Deutsch arbeiten?", "a": "Semantic Scholar kann deutsche Suchanfragen verarbeiten, aber die Datenbank enthält überwiegend englischsprachige Publikationen. Für deutschsprachige wissenschaftliche Literatur sind Datenbanken wie DBIS oder spezifische Fach-Repositorien besser."}]$t31fq$::JSONB WHERE slug = 'scite' AND lang = 'de';
UPDATE tools SET choose_if = $t32ci$["✅ Kostenloser Zugang zur größten akademischen Literaturdatenbank mit KI-Zusammenfassungen", "✅ Sie möchten schnell relevante Paper zu einem Thema finden und Paper-Empfehlungen erhalten", "✅ Einstieg in ein neues Forschungsgebiet ohne kommerzielle Abonnementkosten", "✅ Semantische Suche findet konzeptuell ähnliche Paper auch ohne exakte Keyword-Treffer"]$t32ci$::JSONB, faq = $t32fq$[{"q": "Was sind Smart Citations bei Scite?", "a": "Scite analysiert wie Studien in späteren Papers zitiert werden — ob die zitierende Studie die ursprüngliche Findung unterstützt, widerlegt oder neutral erwähnt. Das gibt Ihnen sofort einen Überblick über die wissenschaftliche Akzeptanz einer Studie."}, {"q": "Ist Semantic Scholar kostenlos?", "a": "Ja. Semantic Scholar ist vollständig kostenlos auf semanticscholar.org. Es wird vom Allen Institute for AI betrieben. Scite hat einen kostenlosen Plan mit begrenztem Zugang; kostenpflichtige Pläne ab $20/Monat."}, {"q": "Scite vs PubMed: Was ist besser?", "a": "PubMed ist die primäre Datenbank für biomedizinische Literatur — am vollständigsten und aktuellsten für Medizin. Scite fügt eine wichtige Dimension hinzu: die Qualität der Zitationen. Für biomedizinische Forschung — PubMed als Primärquelle, Scite für Qualitätsbewertung."}, {"q": "Kann Semantic Scholar auf Deutsch arbeiten?", "a": "Semantic Scholar kann deutsche Suchanfragen verarbeiten, aber die Datenbank enthält überwiegend englischsprachige Publikationen. Für deutschsprachige wissenschaftliche Literatur sind Datenbanken wie DBIS oder spezifische Fach-Repositorien besser."}]$t32fq$::JSONB WHERE slug = 'semantic-scholar' AND lang = 'de';
UPDATE tools SET choose_if = $t33ci$["✅ Sie möchten eine App aus Airtable oder Google Sheets in Minuten erstellen ohne technische Kenntnisse", "✅ Softr ist einfacher: Vorgefertigte Templates für Mitgliederportale, Kundenportale und Verzeichnisse", "✅ Sie benötigen Benutzerauthentifizierung und Portale für Kunden oder Mitglieder schnell und einfach", "✅ Kleinere Projekte die schnell live gehen sollen ohne Bubble's steilere Lernkurve"]$t33ci$::JSONB, faq = $t33fq$[{"q": "Was ist Softr?", "a": "Softr ist ein No-Code-Tool das Webanwendungen und Portale aus Airtable oder Google Sheets erstellt. Typische Anwendungen: Mitglieder-Portale, Kunden-Dashboards, Job-Boards, Verzeichnisse. Es ist einfacher als Bubble aber weniger flexibel."}, {"q": "Softr vs Webflow: Was ist besser?", "a": "Softr ist besser für datengesteuerte Apps mit Benutzerauthentifizierung (Mitgliederportale, Kundenportale). Webflow ist besser für Marketing-Websites und Content-Sites. Softr für App-Logik aus Daten; Webflow für Design-orientierte Websites."}, {"q": "Ist Softr kostenlos?", "a": "Softr hat einen kostenlosen Plan für einfache Apps mit bis zu 100 Benutzern. Starter ab $49/Monat, Pro ab $167/Monat für mehr Features und Benutzer. Bubble hat einen kostenlosen Plan; ab $29/Monat zum Veröffentlichen."}, {"q": "Kann Softr mit Airtable verbinden?", "a": "Ja. Airtable ist Softr's primäre Datenquelle. Sie verbinden Ihre Airtable-Base und Softr erstellt automatisch die App-Struktur basierend auf Ihren Feldern und Ansichten. Das ist einer der schnellsten Wege von Daten zu einer funktionierenden Web-App."}]$t33fq$::JSONB WHERE slug = 'softr' AND lang = 'de';
UPDATE tools SET choose_if = $t34ci$["✅ Sie möchten vollständige Songs mit Gesang, Instrumentierung und Produktion aus Text generieren", "✅ Sie benötigen Hintergrundmusik für Videos, Podcasts oder Social-Media-Content", "✅ Keine Musikproduktionskenntnisse erforderlich — Suno macht aus Text komplette Songs", "✅ Großzügiger kostenloser Plan für Musikexperimente ohne sofortige Kosten"]$t34ci$::JSONB, faq = $t34fq$[{"q": "Suno oder ElevenLabs: Was ist der Unterschied?", "a": "Suno generiert Musik und Songs mit Gesang. ElevenLabs generiert gesprochene Sprache und Voiceovers. Das sind grundlegend verschiedene Anwendungsfälle. Für Musik und Jingles — Suno; für Voiceovers und TTS — ElevenLabs."}, {"q": "Kann Suno deutsche Songs erstellen?", "a": "Ja. Suno kann Songs in deutschen Texten generieren. Geben Sie deutschen Liedtext in Custom Lyrics ein oder beschreiben Sie den Stil auf Deutsch. Die Qualität deutschsprachiger Songs ist gut, für Englisch aber noch konsistenter."}, {"q": "Ist Suno kostenlos?", "a": "Suno hat einen kostenlosen Plan mit 50 Credits/Tag (ca. 10 Songs). Pro ab $10/Monat (500 Credits), Premier ab $30/Monat. ElevenLabs hat einen kostenlosen Plan; Starter ab $5/Monat."}, {"q": "Kann ElevenLabs Musik generieren?", "a": "ElevenLabs fokussiert auf Text-zu-Sprache und Stimmen — keine Musik-Generierung. Für Musik nutzen Sie Suno oder Udio. ElevenLabs hat jedoch Sound Effects generierung als separate Funktion."}]$t34fq$::JSONB WHERE slug = 'suno' AND lang = 'de';
UPDATE tools SET choose_if = $t35ci$["✅ Sie möchten Mathe-Lernspiele für Kinder (5-14 Jahre) die echten Spaß machen und Ergebnisse liefern", "✅ Synthesis nutzt spielbasiertes Lernen: Kinder lösen mathematische Probleme in kompetitiven Spielen", "✅ Eltern die eine engagierende Mathematik-Ergänzung zum Schulunterricht suchen", "✅ Kinder die durch Gamification mehr Freude am Lernen entwickeln als mit traditionellen Methoden"]$t35ci$::JSONB, faq = $t35fq$[{"q": "Was ist Synthesis?", "a": "Synthesis ist eine Lernplattform ursprünglich für SpaceX-Mitarbeiterkinder entwickelt. Es nutzt kollaborative Spiele und Simulationen um mathematisches Denken zu fördern. Kinder 5-14 Jahre spielen zusammen und lösen dabei komplexe mathematische Probleme."}, {"q": "Wie viel kostet Synthesis?", "a": "Synthesis kostet $35/Monat. Khanmigo kostet $4/Monat als Add-on. Synthesis ist teurer aber bietet eine engagierende Spiel-Erfahrung. Für Eltern die ein engagierendes Mathe-Lernspiel suchen — Synthesis; für günstigen breiten Tutor — Khanmigo."}, {"q": "Synthesis für deutschsprachige Kinder: Ist es geeignet?", "a": "Synthesis ist primär auf Englisch. Die mathematischen Konzepte sind sprachübergreifend, aber die Spielanleitungen und Kommunikation sind auf Englisch. Für deutschsprachige Kinder ohne gute Englischkenntnisse kann das eine Barriere sein."}, {"q": "Synthesis vs Prodigy: Was ist besser?", "a": "Prodigy ist kostenlos und breit verfügbar für Grundschul-Mathe. Synthesis ist teurer aber hat komplexere, kollaborative Lernspiele. Prodigy für einfaches Mathe-Üben; Synthesis für tieferes mathematisches Denken und kollaborative Problemlösung."}]$t35fq$::JSONB WHERE slug = 'synthesis' AND lang = 'de';
UPDATE tools SET choose_if = $t36ci$["✅ Sie analysieren große komplexe Datensätze und benötigen fortgeschrittene analytische Visualisierungen", "✅ Enterprise-Teams mit Data Warehouse, Datenbank-Verbindungen und komplexen Daten-Modellen", "✅ Sie benötigen KI-gestützte Einblicke: Tableau AI erklärt Trends und Anomalien automatisch", "✅ Datenanalysten und Business-Intelligence-Teams die Tableau als Industriestandard nutzen"]$t36ci$::JSONB, faq = $t36fq$[{"q": "Looker Studio vs Tableau: Was ist besser?", "a": "Looker Studio (kostenlos) ist ideal für Google-Ökosystem-Daten und einfache Marketing-Dashboards. Tableau ist leistungsfähiger für komplexe Unternehmensanalysen aber kostet ab $75/Benutzer/Monat. Für kleine Teams und Marketing — Looker Studio; für Enterprise-BI — Tableau."}, {"q": "Ist Looker Studio wirklich kostenlos?", "a": "Ja. Looker Studio ist vollständig kostenlos für Einzelnutzer. Looker Studio Pro kostet $9/Benutzer/Monat und fügt erweiterte Verwaltungs- und Kollaborations-Features für Teams hinzu."}, {"q": "Kann Tableau AI natürliche Sprache verwenden?", "a": "Ja. Tableau hat Ask Data und Tableau AI Features die natürlichsprachige Fragen zu Ihren Daten ermöglichen. Sie können fragen 'Was waren unsere Top-Produkte letztes Quartal?' und Tableau generiert die Visualisierung."}, {"q": "Looker Studio vs Power BI: Was ist besser?", "a": "Beide sind starke Dashboard-Tools. Looker Studio ist kostenlos und Google-zentriert. Power BI ($10/Benutzer/Monat) ist tiefer in Microsoft 365 integriert und leistungsfähiger für komplexe Datenmodelle. Im Google-Ökosystem — Looker Studio; im Microsoft-Ökosystem — Power BI."}]$t36fq$::JSONB WHERE slug = 'tableau-ai' AND lang = 'de';
UPDATE tools SET choose_if = $t37ci$["✅ Sie möchten professionelle pixel-perfekte Marketing-Websites und CMS-Seiten ohne Code", "✅ Designer die volle visuelle Kontrolle über das Design wollen ohne auf Templates beschränkt zu sein", "✅ Content-Sites mit CMS: Blog, Produktseiten, Landing-Pages die regelmäßig aktualisiert werden", "✅ Agenturen die Kunden-Websites mit sauberem, performantem Code ohne Backend-Komplexität bauen"]$t37ci$::JSONB, faq = $t37fq$[{"q": "Bubble oder Webflow: Was soll ich wählen?", "a": "Bubble für Web-Apps: Sie brauchen Nutzeraccounts, Datenbank und komplexe Logik — z.B. ein SaaS-Produkt oder Marktplatz. Webflow für Marketing-Websites: Sie brauchen eine schöne, schnelle Website mit CMS aber keine App-Logik."}, {"q": "Ist Bubble kostenlos?", "a": "Bubble hat einen kostenlosen Plan der das Bauen und Testen erlaubt. Kostenpflichtige Pläne ab $29/Monat zum Veröffentlichen ohne Bubble-Branding. Webflow hat einen kostenlosen Plan; kostenpflichtige Pläne ab $18/Monat."}, {"q": "Kann Bubble eine App für den App-Store erstellen?", "a": "Bubble erstellt Web-Apps die im Browser laufen. Für native iOS/Android-Apps können Sie Bubble-Apps als PWA verpacken oder Tools wie BDK Native verwenden. Für echte native Apps sind FlutterFlow oder React Native besser geeignet."}, {"q": "Webflow für E-Commerce: Ist das gut?", "a": "Webflow hat eingebautes E-Commerce für einfache Online-Shops. Für komplexere E-Commerce-Anforderungen (große Produktkataloge, komplexe Varianten) ist Shopify leistungsfähiger. Webflow ist gut für Design-orientierte kleine Shops."}]$t37fq$::JSONB WHERE slug = 'webflow' AND lang = 'de';
UPDATE tools SET choose_if = $t38ci$["✅ Sie möchten YouTube-Videos und Kursvideos in interaktive Lern-Sessions verwandeln", "✅ YouLearn generiert Quizze, Zusammenfassungen und Karteikarten aus Video-Content automatisch", "✅ Sie lernen aus Online-Kursen und möchten aktives Lernen statt passives Zuschauen", "✅ Studenten die Videovorlesungen effizienter nutzen und behalten wollen"]$t38ci$::JSONB, faq = $t38fq$[{"q": "Was ist YouLearn?", "a": "YouLearn ist ein KI-Lernassistent der YouTube-Videos und Dokumente in interaktive Lernmaterialien umwandelt. Er generiert automatisch Zusammenfassungen, Quizfragen und Karteikarten aus dem Video-Content und ermöglicht Fragen an das Video zu stellen."}, {"q": "YouLearn vs Recall: Was ist besser?", "a": "Recall ist breiter: Es speichert und verknüpft Wissen aus allen Quellen (Web, PDFs, Videos) in einer persönlichen Wissensdatenbank. YouLearn ist fokussierter auf aktives Lernen aus Videos mit Quiz-Generierung. Für Wissensmanagement — Recall; für aktives Lernen aus Videos — YouLearn."}, {"q": "Ist YouLearn kostenlos?", "a": "YouLearn hat eine kostenlose Version mit begrenzten Funktionen. Kostenpflichtige Pläne bieten unbegrenzte Verarbeitung. NotebookLM ist vollständig kostenlos."}, {"q": "Kann YouLearn deutsche YouTube-Videos verarbeiten?", "a": "Ja. YouLearn kann deutsche Videos transkribieren und analysieren. Die Qualität hängt von der Audio-Qualität des Videos ab. Gut artikulierte deutschsprachige Vorlesungen und Kurse werden gut verarbeitet."}]$t38fq$::JSONB WHERE slug = 'youlearn' AND lang = 'de';
UPDATE tools SET choose_if = $t39ci$["✅ Sie möchten Workflows zwischen verschiedenen Apps automatisieren: CRM, E-Mail, Datenbanken, Slack", "✅ KI-gestützte Automation ohne Code: beschreiben Sie den Workflow und Zapier baut ihn", "✅ Sie integrieren Daten aus dutzenden Tools in automatisierte Multi-Step-Prozesse", "✅ Sie benötigen KI-Agenten die auf Trigger reagieren und komplexe Workflows ausführen"]$t39ci$::JSONB, faq = $t39fq$[{"q": "Notion AI vs ChatGPT: Was ist besser?", "a": "Notion AI ist nativ in Notion integriert und arbeitet mit Ihren vorhandenen Dokumenten. ChatGPT ist ein eigenständiger Assistent ohne Ihre Dokument-Basis. Notion AI für bestehende Notion-Nutzer; ChatGPT für allgemeine KI-Aufgaben außerhalb von Notion."}, {"q": "Was kostet Notion AI?", "a": "Notion AI ist ein Add-on für $10/Benutzer/Monat zusätzlich zum Notion-Plan. Zapier hat eine kostenlose Version mit 100 Aufgaben/Monat; kostenpflichtige Pläne ab $29,99/Monat."}, {"q": "Kann Zapier KI-Workflows erstellen?", "a": "Ja. Zapier hat KI-Funktionen: AI-gestützte Zap-Generierung, Formatter mit KI und AI-Steps in Workflows. Sie können KI-Verarbeitung als Schritt in Automationen einbauen — z.B. E-Mail-Inhalt zusammenfassen und in Notion speichern."}, {"q": "Notion AI für Teams: Ist es gut?", "a": "Ja. Notion AI ist besonders wertvoll für Teams die Notion als zentrales Wissens-Hub nutzen. Es kann Meeting-Notizen automatisch zusammenfassen, Action Items extrahieren und Dokumente übersetzen — direkt in Ihren bestehenden Workflows."}]$t39fq$::JSONB WHERE slug = 'zapier-ai' AND lang = 'de';
COMMIT;